declare(strict_types=1);
function eqs_topics(): array {
 return [
 'introduce'=>['Giới thiệu bản thân','a new classmate',['My name is Linh. I am from Vietnam.','I live in Da Nang and enjoy reading in my free time.','I am studying English because I would like to meet people from other countries.','Although I work full time, I make a habit of practising English every evening.','Having grown up in a small coastal town, I have always been curious about how people live elsewhere.','My background has shaped my perspective, yet I am keen to question my assumptions through conversations with people whose experiences differ from mine.']],
 'restaurant'=>['Gọi món tại nhà hàng','a restaurant server',['I would like water, please.','Could I have a chicken sandwich and a cup of tea?','Could you tell me whether this dish contains any nuts?','I would prefer something light, but I am happy to try a local speciality.','Would it be possible to substitute the cream sauce with something suitable for someone who avoids dairy?','While I appreciate the recommendation, could you suggest an alternative that retains the character of the dish without relying on ingredients I cannot eat?']],
 'directions'=>['Hỏi đường','a local resident',['Where is the bus stop?','Go straight and turn left at the bank.','Is there a convenient way to get to the museum by public transport?','I seem to have taken the wrong exit; could you point me towards the main square?','Given the road closures, which route would you recommend for someone travelling on foot?','Could you clarify whether the diversion rejoins the original route before the station, or whether I should allow additional time to reach the other entrance?']],
 'shopping'=>['Mua sắm','a shop assistant',['How much is this shirt?','Do you have this shirt in a smaller size?','Could I exchange this item if it does not fit?','I am comparing a few options and would like to understand what the warranty covers.','Before I decide, could you explain how the materials affect durability and whether repairs are available?','The initial price is only one consideration; I would also like to weigh the long-term maintenance costs against the environmental implications of replacing it.']],
 'interview'=>['Phỏng vấn xin việc','a job interviewer',['I am a student. I like learning.','I worked in a small shop last summer.','I helped my team finish a project before the deadline.','When priorities changed, I reorganised the workload and kept everyone informed.','A disagreement about our approach prompted me to test both proposals against clearly defined success criteria.','Rather than presenting that setback as an isolated failure, I would highlight how it exposed weaknesses in our assumptions and led to a more resilient decision-making process.']],
 'work'=>['Giao tiếp công sở','a colleague',['The meeting is at ten.','Can we meet after lunch to discuss the plan?','I will send you an update once I have checked the figures.','Could we agree on the priorities before we commit to the revised deadline?','My main concern is that reducing the testing period could introduce risks that outweigh the short-term gains.','If we distinguish between essential safeguards and processes that add little value, we may be able to meet the deadline without compromising the integrity of the outcome.']],
 'travel'=>['Du lịch','a hotel receptionist',['I have a reservation.','Could I check in early and leave my bag here?','My flight has been delayed, so I may arrive after midnight.','If the connection is cancelled, would it be possible to change the booking without a fee?','I would appreciate advice on less crowded routes that still allow us to experience the area responsibly.','Rather than treating each stop as a box to tick, I would prefer an itinerary that leaves room for unplanned encounters while respecting the needs of the communities we visit.']],
 'daily'=>['Sinh hoạt hằng ngày','a study partner',['I wake up at six.','I usually have breakfast before I go to work.','I used to study late at night, but I now prefer the morning.','I have found that setting small goals makes it easier to keep a consistent routine.','By adjusting my routine around periods when I concentrate best, I have been able to make more effective use of limited study time.','A sustainable routine depends less on rigid self-discipline than on recognising competing demands and designing habits that can withstand inevitable disruptions.']],
 'ielts1'=>['IELTS Speaking Part 1','an examiner asking short personal questions',['I like my hometown.','My hometown is quiet and close to the sea.','What I like most about my hometown is that people are friendly and helpful.','Although it has become busier, my hometown still has the relaxed atmosphere I remember.','The most appealing aspect of my hometown is the balance between a close-knit community and access to a wider range of opportunities.','What gives my hometown its character is not any single landmark, but the subtle interplay between its changing streetscape and the social traditions that have endured.']],
 'ielts2'=>['IELTS Speaking Part 2','an examiner; ask me to describe a place I enjoyed visiting',['I visited a park. It was beautiful.','I went to a park with my family last month.','I would like to describe a small garden I visited with a close friend last spring.','What made the visit memorable was the contrast between the busy streets outside and the quiet atmosphere inside.','I had expected a brief stop, but the carefully designed paths and the changing light encouraged us to slow down and explore.','Looking back, the significance of that visit lay less in the scenery itself than in the way the place altered our sense of time and made an ordinary afternoon unexpectedly memorable.']],
 'ielts3'=>['IELTS Speaking Part 3','an examiner discussing tourism and local communities',['Travel can help people learn.','Tourists can help local shops earn money.','Tourism can create jobs, but local people may also face higher prices.','Whether tourism benefits a community depends largely on how the income is distributed and how development is managed.','The challenge is to reconcile economic opportunities with the preservation of cultural practices that may be altered by commercial demand.','Any assessment of tourism should account for the asymmetry between those who capture its financial benefits and those who bear its social and environmental costs.']],
 ];
}
function eqs_catalog(): array {
 $out=[];$starter=json_decode(file_get_contents(__DIR__.'/starter-course.json'),true,64,JSON_THROW_ON_ERROR);$seen=[];
 foreach($starter['units'] as $u)foreach($u['lessons'] as $l)if($l['id']!=='starter-alphabet')foreach($l['content']['vocabulary'] as $i=>$w){if(isset($seen[strtolower($w['en'])]))continue;$seen[strtolower($w['en'])]=1;$out[]=['key'=>'word-'.$l['id'].'-'.$i,'mode'=>'word','level'=>'A1','topic'=>'vocabulary','title'=>$w['en'],'sample'=>$w['en'],'ipa'=>$w['ipa'],'vi'=>$w['vi'],'example'=>$w['example'],'tip'=>'Nghe mẫu rồi đọc rõ từng từ. Phiên âm là hướng dẫn; độ khớp văn bản không phải điểm phát âm.'];}
 $extra=[['A2','journey','/ˈdʒɜːni/','hành trình'],['A2','improve','/ɪmˈpruːv/','cải thiện'],['B1','opportunity','/ˌɒpəˈtjuːnəti/','cơ hội'],['B1','confident','/ˈkɒnfɪdənt/','tự tin'],['B2','perspective','/pəˈspektɪv/','góc nhìn'],['B2','negotiate','/nɪˈɡəʊʃieɪt/','đàm phán'],['C1','sustainable','/səˈsteɪnəbl/','bền vững'],['C1','ambiguity','/ˌæmbɪˈɡjuːəti/','sự mơ hồ'],['C2','meticulous','/məˈtɪkjələs/','tỉ mỉ'],['C2','juxtaposition','/ˌdʒʌkstəpəˈzɪʃn/','sự đặt cạnh nhau để đối chiếu']];
 foreach($extra as [$level,$word,$ipa,$vi])$out[]=['key'=>'word-'.$word,'mode'=>'word','level'=>$level,'topic'=>'vocabulary','title'=>$word,'sample'=>$word,'ipa'=>$ipa,'vi'=>$vi,'tip'=>'Chú ý dấu trọng âm trong IPA; nghe và đọc lại.'];
 foreach(eqs_topics() as $key=>$topic)foreach(['A1','A2','B1','B2','C1','C2'] as $i=>$level)foreach(['sentence','scenario'] as $mode)$out[]=['key'=>$mode.'-'.$key.'-'.$level,'mode'=>$mode,'level'=>$level,'topic'=>$key,'title'=>$topic[0],'sample'=>$topic[2][$i],'ipa'=>'','vi'=>$mode==='sentence'?'Luyện đọc theo câu mẫu.':'Đặt mình vào tình huống và thử trả lời; câu bên dưới là gợi ý tham khảo.','tip'=>$mode==='scenario'?'Bạn có thể diễn đạt khác câu gợi ý. Độ khớp chỉ cho biết mức giống văn bản mẫu, không quyết định câu nói của bạn có đúng hay không.':'Nghe theo cụm, chú ý nhịp và trọng âm. Kết quả chỉ phản ánh văn bản được nhận diện.'];
 return $out;
}
function eqs_task(string $key): ?array {foreach(eqs_catalog() as $t)if($t['key']===$key)return $t;return null;}
